const FORBIDDEN_UNTRACKED_PATTERNS = [
  /^\.env(\..+)?$/i,
  /credentials/i,
  /secrets/i,
  /\.(pem|key|pfx|pkcs12)$/i,
  /\.(db|sqlite|sqlite3|backup|bak)$/i,
  /\.(zip|tar|gz|tgz|7z|rar)$/i,
  /\.log$/i,
  /^node_modules[\\\/]/i,
  /^(build|dist|\.next|\.nuxt|\.turbo|\.dsh_worktrees|\.worktrees)[\\\/]/i,
  /^\.git[\\\/]/i
];

function printUsage() {
  console.log(`
Usage: node dsh-delegate.js [options]

Options:
  --role <role>              ${VALID_ROLES.join(' | ')} (Default: DSH_IMPLEMENTER)
  --objective <text>         Primary goal / objective of the task (Required)
  --targetPath <dir>         Target project directory (Default: current directory)
  --worktreePath <dir>       Reuse existing worktree (for DSH_FIXER or chained steps)
  --baseCommit <hash>        Base snapshot commit for existing worktree
  --allowedScope <paths>     Comma-separated allowed files/folders
  --forbiddenScope <paths>   Comma-separated forbidden files/folders
  --constraints <text>       Additional engineering constraints
  --findings <text>          Verified reviewer findings (for DSH_FIXER)
  --definitionOfDone <text>  Explicit acceptance criteria
  --noWorktree               Bypass worktree creation (read-only tasks default to no worktree)
  --dryRun                   Print task specification and execution plan without running
`);
}

function parseArgs(args) {
  const result = {
    role: 'DSH_IMPLEMENTER',
    objective: '',
    targetPath: process.cwd(),
    worktreePath: '',
    baseCommit: '',
    allowedScope: '',
    forbiddenScope: '.env, *.env*, credentials*, secrets*, node_modules, .git',
    constraints: '',
    findings: '',
    definitionOfDone: '',
    noWorktree: false,
    dryRun: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--role' && i + 1 < args.length) {
      let r = args[++i].toUpperCase();
      if (!r.startsWith('DSH_')) r = `DSH_${r}`;
      result.role = VALID_ROLES.includes(r) ? r : 'DSH_IMPLEMENTER';
    }
    else if (arg === '--mode' && i + 1 < args.length) {
      const m = args[++i].toUpperCase();
      if (m === 'READ_ONLY_AUDIT') result.role = 'DSH_SECURITY_REVIEWER';
      else if (m === 'INDEPENDENT_REVIEW') result.role = 'DSH_CODE_REVIEWER';
      else if (m === 'TEST_GENERATION' || m === 'TEST_GEN') result.role = 'DSH_TESTER';
      else if (m === 'RESEARCH' || m === 'PLAN') result.role = 'DSH_PLANNER';
      else result.role = 'DSH_IMPLEMENTER';
    }
    else if (arg === '--objective' && i + 1 < args.length) result.objective = args[++i];
    else if (arg === '--targetPath' && i + 1 < args.length) result.targetPath = path.resolve(args[++i]);
    else if (arg === '--worktreePath' && i + 1 < args.length) result.worktreePath = path.resolve(args[++i]);
    else if (arg === '--baseCommit' && i + 1 < args.length) result.baseCommit = args[++i];
    else if (arg === '--allowedScope' && i + 1 < args.length) result.allowedScope = args[++i];
    else if (arg === '--forbiddenScope' && i + 1 < args.length) result.forbiddenScope = args[++i];
    else if (arg === '--constraints' && i + 1 < args.length) result.constraints = args[++i];
    else if (arg === '--findings' && i + 1 < args.length) result.findings = args[++i];
    else if (arg === '--definitionOfDone' && i + 1 < args.length) result.definitionOfDone = args[++i];
    else if (arg === '--noWorktree') result.noWorktree = true;
    else if (arg === '--dryRun') result.dryRun = true;
    else if (arg === '--help' || arg === '-h') {
      printUsage();
      process.exit(0);
    }
  }

  return result;
}

function isGitRepo(dir) {
  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

function isForbiddenUntracked(filePath) {
  const normalized = filePath.replace(/\\/g, '/');
  return FORBIDDEN_UNTRACKED_PATTERNS.some((pattern) => pattern.test(normalized) || pattern.test(path.basename(normalized)));
}

function getAgencyPrompt(role) {
  const norm = role.toLowerCase().replace(/^dsh_/, '').replace(/^dsh-/, '');
  const slug = norm.startsWith('agency-') ? norm : 'agency-' + norm.replace(/_/g, '-');
  
  const searchPaths = [
    `G:\\0000 PY PROGRAM\\_AI_TOOLS\\SUper\\frameworks\\blackpearl-skills\\.opencode\\prompts\\agents\\${slug}.txt`,
    `G:\\0000 PY PROGRAM\\_AI_TOOLS\\SUper\\frameworks\\blackpearl-skills\\skills\\${slug}\\SKILL.md`,
    `C:\\Users\\victo\\.gemini\\config\\skills\\${slug}\\SKILL.md`
  ];

  for (const sp of searchPaths) {
    if (fs.existsSync(sp)) {
      let txt = fs.readFileSync(sp, 'utf8');
      return txt.replace(/^---[\s\S]*?---\s*/, '').trim();
    }
  }
  return null;
}

function isWriteRole(role) {
  const norm = role.toLowerCase();
  if (norm.includes('dev') || norm.includes('engineer') || norm.includes('builder') || norm.includes('coder') || norm.includes('implementer') || norm.includes('fixer') || norm.includes('scripter') || norm.includes('creator') || norm.includes('designer') || norm.includes('tester') || norm.includes('maintainer')) {
    return true;
  }
  return role === 'DSH_IMPLEMENTER' || role === 'DSH_TESTER' || role === 'DSH_FIXER' || role === 'DSH_API_TESTER' || role === 'DSH_INFRA_MAINTAINER' || role === 'DSH_MCP_BUILDER' || role === 'DSH_WORKFLOW_ARCHITECT' || role === 'DSH_VISIONOS_ENGINEER' || role === 'DSH_METAL_ENGINEER' || role === 'DSH_WEBXR_DEVELOPER' || role === 'DSH_UI_DESIGNER' || role === 'DSH_WHIMSY_INJECTOR' || role === 'DSH_BACKEND_ARCHITECT' || role === 'DSH_MOBILE_DEVELOPER' || role === 'DSH_RAG_ENGINEER' || role === 'DSH_PAYMENTS_ENGINEER' || role === 'DSH_DB_OPTIMIZER' || role === 'DSH_SRE_ENGINEER' || role === 'DSH_GIS_DEVELOPER' || role === 'DSH_GAME_DESIGNER';
}

