function getDefaultDoD(role) {
  if (isWriteRole(role)) {
    return '- Implementation complete, tested, and meeting all constraints\n- 0 regressions introduced';
  }
  return '- Independent assessment completed with concrete evidence and actionable findings';
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));

  if (!opts.objective) {
    console.error('Error: --objective is required.');
    printUsage();
    process.exit(1);
  }

  if (!fs.existsSync(DSH_ROOT)) {
    console.error(`Error: DeepSeek Harness repository not found at ${DSH_ROOT}`);
    process.exit(1);
  }

  const targetDir = opts.targetPath;
  const isGit = isGitRepo(targetDir);
  const isWrite = isWriteRole(opts.role);
  const useWorktree = isGit && !opts.noWorktree && isWrite;

  const roleTag = opts.role.toLowerCase().replace('dsh_', '');
  const runId = `orch-run-${roleTag}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;

  let executionDir = targetDir;
  let worktreePath = opts.worktreePath || null;
  let branchName = null;
  let baseSnapshotCommit = opts.baseCommit || null;
  let isNewWorktreeCreated = false;

  if (opts.dryRun) {
    const simulatedWorktree = path.resolve(targetDir, '.worktrees', `dsh-${runId}`);
    const simulatedPrompt = buildTaskPrompt(opts, runId, isWrite ? simulatedWorktree : targetDir);
    console.log('\n==================================================');
    console.log(`[Antigravity Lead] (DRY RUN) DEEPSEEK HARNESS AGENT: ${opts.role}`);
    console.log(`ORCHESTRATION RUN ID: ${runId}`);
    console.log(`MODE: ${isWrite ? 'WRITE / ISOLATED WORKTREE' : 'SOFT READ-ONLY (Prompt Enforced)'}`);
    console.log(`WORKSPACE: ${isWrite ? simulatedWorktree : targetDir}`);
    console.log('==================================================\n');
    console.log(simulatedPrompt);
    console.log('\n[Antigravity Lead] Dry run complete. Exiting.');
    return;
  }

  if (useWorktree) {
    if (worktreePath && fs.existsSync(worktreePath)) {
      executionDir = worktreePath;
      console.log(`[Antigravity Lead] Reusing existing worktree for ${opts.role} at ${worktreePath}`);
    } else {
      branchName = `dsh/${runId}`;
      const worktreesBase = path.resolve(targetDir, '.worktrees');
      if (!fs.existsSync(worktreesBase)) {
        try { fs.mkdirSync(worktreesBase, { recursive: true }); } catch {}
      }
      worktreePath = path.resolve(worktreesBase, `dsh-${runId}`);

      let isDirty = false;
      try {
        const statusOutput = execSync('git status --porcelain', { cwd: targetDir, encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 }).trim();
        isDirty = statusOutput.length > 0;
      } catch (err) {
        console.error(`[Antigravity Lead] FATAL: Failed to inspect git status (${err.message}).`);
        console.error('DSH_WRITE_ABORTED: WORKSPACE_INSPECTION_FAILED');
        process.exit(2);
      }

      console.log(`[Antigravity Lead] Workspace state: ${isDirty ? 'DIRTY (Uncommitted changes detected)' : 'CLEAN'}`);
      console.log(`[Antigravity Lead] Spawning ${opts.role} in isolated worktree: ${worktreePath} (Branch: ${branchName})...`);

      try {
        execSync(`git worktree add -b "${branchName}" "${worktreePath}"`, { cwd: targetDir, stdio: 'inherit' });
        executionDir = worktreePath;
        isNewWorktreeCreated = true;
      } catch (err) {
        console.error(`[Antigravity Lead] FATAL: Worktree creation failed (${err.message}).`);
        console.error('DSH_WRITE_ABORTED: WORKTREE_CREATION_FAILED');
        process.exit(2);
      }

      if (isDirty) {
        console.log('[Antigravity Lead] Reproducing active workspace snapshot into isolated worktree...');
        try {
          const trackedDiff = execSync('git diff HEAD --binary', { cwd: targetDir, maxBuffer: 100 * 1024 * 1024 });
          if (trackedDiff.length > 0) {
            execSync('git apply --binary --whitespace=nowarn', {
              cwd: worktreePath,
              input: trackedDiff,
              maxBuffer: 100 * 1024 * 1024,
            });
          }

          let untrackedFiles = [];
          try {
            const rawUntracked = execSync('git ls-files --others --exclude-standard', { cwd: targetDir, encoding: 'utf-8', maxBuffer: 100 * 1024 * 1024 });
            untrackedFiles = rawUntracked.split('\n').map((s) => s.trim()).filter(Boolean);
          } catch {}

          let copiedCount = 0;
          for (const relFile of untrackedFiles) {
            if (isForbiddenUntracked(relFile)) continue;
            const srcPath = path.join(targetDir, relFile);
            const destPath = path.join(worktreePath, relFile);
            try {
              if (fs.existsSync(srcPath) && fs.statSync(srcPath).isFile()) {
                fs.mkdirSync(path.dirname(destPath), { recursive: true });
                fs.copyFileSync(srcPath, destPath);
                copiedCount++;
              }
            } catch {}
          }

          execSync('git add -A', { cwd: worktreePath });
          execSync('git commit -m "chore(dsh): baseline user workspace snapshot" --allow-empty', {
            cwd: worktreePath,
            env: {
              ...process.env,
              GIT_AUTHOR_NAME: 'Antigravity Snapshot',
              GIT_AUTHOR_EMAIL: 'antigravity-snapshot@local',
              GIT_COMMITTER_NAME: 'Antigravity Snapshot',
              GIT_COMMITTER_EMAIL: 'antigravity-snapshot@local',
            },
          });

          baseSnapshotCommit = execSync('git rev-parse HEAD', { cwd: worktreePath, encoding: 'utf-8' }).trim();
          console.log(`[Antigravity Lead] Base Snapshot established at commit: ${baseSnapshotCommit.slice(0, 8)}`);
        } catch (snapshotErr) {
          console.error(`[Antigravity Lead] FATAL: Snapshot replication failed (${snapshotErr.message}).`);
          try { execSync(`git worktree remove "${worktreePath}" --force`, { cwd: targetDir, stdio: 'ignore' }); } catch {}
          try { execSync(`git branch -D "${branchName}"`, { cwd: targetDir, stdio: 'ignore' }); } catch {}
          console.error('DSH_WRITE_ABORTED: DIRTY_WORKSPACE_SNAPSHOT_FAILED');
          process.exit(2);
        }
      } else {
        try {
          baseSnapshotCommit = execSync('git rev-parse HEAD', { cwd: worktreePath, encoding: 'utf-8' }).trim();
        } catch {
          baseSnapshotCommit = 'HEAD';
        }
      }
    }
  } else if (isWrite && !isGit) {
    console.error('[Antigravity Lead] FATAL: Write mode requires a git repository for worktree isolation.');
    console.error('DSH_WRITE_ABORTED: NOT_A_GIT_REPOSITORY');
    process.exit(2);
  }

  const taskPrompt = buildTaskPrompt(opts, runId, executionDir);

  console.log('\n==================================================');
  console.log(`[Antigravity Lead] INITIATING DEEPSEEK HARNESS AGENT: ${opts.role}`);
  console.log(`ORCHESTRATION RUN ID: ${runId}`);
  console.log(`MODE: ${isWrite ? 'WRITE / ISOLATED WORKTREE' : 'SOFT READ-ONLY (Prompt Enforced)'}`);
  console.log(`WORKSPACE: ${executionDir}`);
  console.log('==================================================\n');

  console.log(`[Antigravity Lead] Spawning DeepSeek Harness headless worker process in: ${DSH_ROOT}`);

  const dshProcess = spawn(
    'pnpm',
    ['dsh', '--profile', 'headless', taskPrompt],
    {
      cwd: DSH_ROOT,
      stdio: 'inherit',
      shell: true,
      env: {
        ...process.env,
        DSH_CWD: executionDir,
      },
    }
  );

  dshProcess.on('close', (code) => {
    console.log('\n==================================================');
    console.log(`DEEPSEEK HARNESS AGENT RUN FINISHED: ${opts.role}`);
    console.log(`ORCHESTRATION RUN ID: ${runId}`);
    console.log(`EXIT CODE: ${code}`);
    console.log('==================================================\n');

    let diffStat = '';
    let untrackedAfter = '';

    if (worktreePath && fs.existsSync(worktreePath)) {
      try {
        console.log('==================================================');
        console.log('DSH RESULT - BASE SNAPSHOT DIFF');
        console.log('==================================================');
        if (baseSnapshotCommit) {
          try {
            diffStat = execSync(`git diff "${baseSnapshotCommit}" --stat`, { cwd: worktreePath, encoding: 'utf-8' }).trim();
          } catch {}
        } else {
          try {
            diffStat = execSync('git diff HEAD --stat', { cwd: worktreePath, encoding: 'utf-8' }).trim();
          } catch {}
        }

        try {
          untrackedAfter = execSync('git ls-files --others --exclude-standard', { cwd: worktreePath, encoding: 'utf-8' }).trim();
        } catch {}

        if (diffStat) {
          console.log('\nModified/Created Tracked Files:');
          console.log(diffStat);
        }
        if (untrackedAfter) {
          console.log('\nNew Untracked Files Created by DSH:');
          console.log(untrackedAfter);
        }
        if (!diffStat && !untrackedAfter) {
          console.log('(No file modifications detected from DeepSeek Harness execution)');
        }
      } catch (err) {
        console.warn(`[Antigravity Lead] Warning: Could not compute post-execution diff: ${err.message}`);
      }
    }

    console.log('\n==================================================');
    console.log('DSH AGENT RUN RECORD');
    console.log('==================================================');
    console.log(`ROLE: ${opts.role}`);
    console.log(`ORCHESTRATION RUN ID: ${runId}`);
    console.log(`MODE: ${isWrite ? 'WRITE / ISOLATED WORKTREE' : 'SOFT READ-ONLY (Prompt Enforced)'}`);
    console.log(`WORKSPACE: ${executionDir}`);
    console.log(`BASE COMMIT: ${baseSnapshotCommit || 'N/A'}`);
    console.log(`STATUS: ${code === 0 ? 'SUCCESS' : `EXIT_CODE_${code}`}`);
    if (worktreePath) console.log(`WORKTREE PATH: ${worktreePath}`);
    console.log('==================================================\n');
  });
}

main().catch((err) => {
  console.error('[Antigravity Lead] Unhandled exception:', err);
  process.exit(1);
});
















